    const unpaidPlayers = activePlayers.filter((p) => !p.paid);

    const collectedAmount = paidPlayers.reduce(
      (sum, p) => sum + Number(p.amount || 0),
      0
    );

    const unpaidAmount = unpaidPlayers.reduce(
      (sum, p) => sum + Number(p.amount || 0),
      0
    );

    const expectedAmount = activePlayers.reduce(
